adcs_status_t status = ADCS_OK;
double det_val = 0.0;
double err_val = 0.0;
size_t i, j;

// 1. Check for NULL pointers
if ((dcm == NULL) || (valid == NULL) || (determinant == NULL) || (orthogonality_error == NULL)) {
    return ADCS_E_NULL;
}

// 2. Check for invalid tolerance or non-finite matrix elements
if (!isfinite(tolerance) || tolerance < 0.0) {
    return ADCS_E_RANGE;
}

for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
        if (!isfinite(dcm->m[i][j])) {
            return ADCS_E_RANGE;
        }
    }
}

// 3. Calculate determinant
det_val = adcs_mat3_det(dcm);

// 4. Check determinant sign
if (det_val <= 0.0) {
    *valid = FALSE32;
    *determinant = det_val;
    *orthogonality_error = 0.0;
    return ADCS_OK;
}

// 5. Calculate C * C^T
adcs_mat3_t c_transpose = adcs_mat3_transpose(dcm);
adcs_mat3_t cc_t = adcs_mat3_mul(dcm, &c_transpose);

// 6. Calculate Frobenius error of C*C^T from identity
err_val = adcs_mat3_frobenius_error_identity(&cc_t);

// 7. Check against tolerance
if (err_val > tolerance) {
    *valid = FALSE32;
} else {
    *valid = TRUE32;
}

// 8. Assign output values
*determinant = det_val;
*orthogonality_error = err_val;

return ADCS_OK;

