adcs_status_t status;
double det_val;
double err_val;
adcs_mat3_t c_transpose;
adcs_mat3_t cc_transpose;

// 1. Check NULL pointers
if ((dcm == NULL) || (valid == NULL) || (determinant == NULL) || (orthogonality_error == NULL)) {
    return ADCS_E_NULL;
}

// 2. Check for infinite values in matrix and tolerance validity
// Check if tolerance is finite and non-negative
if (!isfinite(tolerance) || tolerance < 0.0) {
    return ADCS_E_RANGE;
}

// Check if all elements in DCM are finite
size_t i, j;
for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
        if (!isfinite(dcm->m[i][j])) {
            return ADCS_E_RANGE;
        }
    }
}

// 3. Calculate Determinant
det_val = adcs_mat3_det(dcm);

// 4. Calculate Frobenius Error of C * C^T - I
// Compute C^T
c_transpose = adcs_mat3_transpose(dcm);

// Compute M = C * C^T
cc_transpose = adcs_mat3_mul(dcm, &c_transpose);

// Compute Error = Frobenius(M - I)
err_val = adcs_mat3_frobenius_error_identity(&cc_transpose);

// 5. Determine Validity
// Accept only if determinant is positive and error <= tolerance
int is_valid = 0;
if (det_val > 0.0 && err_val <= tolerance) {
    is_valid = 1;
} else {
    is_valid = 0;
}

// 6. Assign outputs
*valid = is_valid ? TRUE32 : FALSE32;
*determinant = det_val;
*orthogonality_error = err_val;

return ADCS_OK;

